// Visual-only, deterministic bounded particle simulation. Never deals damage.
export const FX_CONFIG={capacity:160,life:.65,gravity:.75,drag:2.2,bounce:.38,heavyDamage:12,hitStop:0,cinematicDuration:.38,cinematicFactor:.28,cinematicCooldown:1.2,maxShake:2.2,splatCapacity:48,splatLife:2.6};
const colors={blood:['#ff9292','#ffb0a4','#ff969e','#d4ff91','#e5ffb4','#ceff83','#e7858d','#b9e879','#ff6b6b','#ed454e','#a82938'],spark:['#f6ffe3','#b5ddff','#7aaeff'],poison:['#c8a0ff','#9562cd'],magic:['#71d9ff','#a897ff','#d4a6ff']};
const legacyArena={width:1,height:.72,corner:.07};
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
function validArena(a){return a&&Number.isFinite(a.width)&&a.width>0&&Number.isFinite(a.height)&&a.height>0&&(a.corner===undefined||Number.isFinite(a.corner)&&a.corner>=0&&a.corner<=Math.min(a.width,a.height)/2);}
function arenaFor(run){const a=validArena(run?.arena)?run.arena:legacyArena;return {width:a.width,height:a.height,corner:a.corner??Math.min(legacyArena.corner,a.width/2,a.height/2)};}
function bloodPalette(run,target){
 let hex=run?.[target]?.color;
 if(typeof hex!=='string'||!/^#(?:[\da-f]{3}|[\da-f]{6})$/i.test(hex))return target==='p'?colors.blood.slice(0,3):colors.blood.slice(3,6);
 hex=hex.slice(1);if(hex.length===3)hex=[...hex].map(x=>x+x).join('');
 const rgb=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16));
 // Tint toward white without consuming RNG or losing the victim's randomized hue.
 return [.16,.22,.28].map(amount=>'#'+rgb.map(v=>Math.round(v+(255-v)*amount).toString(16).padStart(2,'0')).join(''));
}
function validColor(kind,color){return kind==='blood'?typeof color==='string'&&/^#[\da-f]{6}$/i.test(color):Object.hasOwn(colors,kind)&&colors[kind].includes(color);}
function contain(p,arena,bounce=true){
 const radius=Math.min(p.radius*(p.kind==='poison'?2:1),arena.width/2,arena.height/2);
 for(const [key,velocity,max]of[['x','vx',arena.width],['y','vy',arena.height]]){
  if(p[key]<radius){p[key]=radius;if(bounce&&p[velocity]<0)p[velocity]=-p[velocity]*FX_CONFIG.bounce;}
  if(p[key]>max-radius){p[key]=max-radius;if(bounce&&p[velocity]>0)p[velocity]=-p[velocity]*FX_CONFIG.bounce;}
 }
 const corner=arena.corner,arc=corner-radius;if(arc<=0)return;
 const cx=clamp(p.x,corner,arena.width-corner),cy=clamp(p.y,corner,arena.height-corner),dx=p.x-cx,dy=p.y-cy,d=Math.hypot(dx,dy);
 if(d>arc){const nx=dx/d,ny=dy/d;p.x=cx+nx*arc;p.y=cy+ny*arc;const speed=p.vx*nx+p.vy*ny;if(bounce&&speed>0){p.vx-=(1+FX_CONFIG.bounce)*speed*nx;p.vy-=(1+FX_CONFIG.bounce)*speed*ny;}}
}
export class ParticleFX{
 constructor(){this.pool=Array.from({length:FX_CONFIG.capacity},()=>({active:false}));this.splats=Array.from({length:FX_CONFIG.splatCapacity},()=>({active:false}));this.reset();}
 reset(run){this.arena=arenaFor(run);this.time=0;this.cursor=run?.eventSeq||0;this.shake=0;this.stop=0;this.spawned=0;this.shakePower=1;this.lastHeavy=-FX_CONFIG.cinematicCooldown;this.rng=1;this.cinematicRemaining=0;this.cinematicDuration=FX_CONFIG.cinematicDuration;this.cinematicFactor=FX_CONFIG.cinematicFactor;this.focusX=this.arena.width/2;this.focusY=this.arena.height/2;for(const s of this.splats)s.active=false;for(const p of this.pool)p.active=false;}
 random(){let x=this.rng|0;x^=x<<13;x^=x>>>17;x^=x<<5;this.rng=x;return (x>>>0)/4294967296;}
 consume(run,reduced=false){this.arena=arenaFor(run);let heavy=false;for(const ev of run.events||[]){const id=ev.id??ev.tick*4+(ev.source==='p'?1:2)+(ev.type==='poison'?1:0);if(id<=this.cursor)continue;this.cursor=id;this.rng=((run.seed^Math.imul(id,2654435761))>>>0)||1;
 if(!Number.isFinite(ev.x)||!Number.isFinite(ev.y))continue;const damage=Number.isFinite(ev.damage)?Math.max(0,ev.damage):0;const targetBody=ev.target==='p'||ev.target==='e';const kind=ev.type==='skill'?'magic':ev.type==='disarm'||ev.type==='recover'||ev.type==='clash'||ev.armor?'spark':ev.type==='poison'?'poison':damage>0&&targetBody?'blood':null;if(!kind)continue;const strength=Math.min(1.6,.4+damage/12),n=reduced?2:kind==='blood'?Math.round(7+strength*7):kind==='spark'?9:kind==='magic'?14:4;
 const palette=kind==='blood'?bloodPalette(run,ev.target):colors[kind];
 const nx=Number.isFinite(ev.nx)?ev.nx:0,ny=Number.isFinite(ev.ny)?ev.ny:-1,angle=Math.atan2(-ny,-nx);
 for(let i=0;i<n;i++){const p=this.pool.find(p=>!p.active);if(!p)break;const a=angle+(this.random()-.5)*(['poison','magic'].includes(kind)?6.28:2.1),v=(.12+this.random()*.55)*strength*Math.min(1.5,.6+(ev.speed||.6));Object.assign(p,{active:true,x:ev.x,y:ev.y,px:ev.x,py:ev.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-.08,z:.012,vz:.10+this.random()*.16,age:0,life:reduced?.16:kind==='poison'?.48:.32+this.random()*.4,radius:kind==='spark'?.0025:.003+this.random()*.005,kind,color:palette[Math.floor(this.random()*palette.length)]});contain(p,this.arena,false);p.px=p.x;p.py=p.y;this.spawned++;}
 if(!reduced&&['hit','projectile','skill'].includes(ev.type)&&targetBody&&damage>0&& (ev.critical||damage>=FX_CONFIG.heavyDamage||this.cinematicRemaining<=0)&&(ev.critical||this.time-this.lastHeavy>=(damage>=FX_CONFIG.heavyDamage?FX_CONFIG.cinematicCooldown:.18)-1e-9)){this.lastHeavy=this.time;this.shakePower=Math.min(1,damage/18);this.shake=Math.max(this.shake,.14);this.cinematicDuration=ev.critical?.38:damage>=FX_CONFIG.heavyDamage?.38:.16;this.cinematicRemaining=this.cinematicDuration;if(ev.critical){this.shake=.28;this.shakePower=1.8;}this.focusX=clamp(ev.x,0,this.arena.width);this.focusY=clamp(ev.y,0,this.arena.height);heavy=true;}
 }return heavy;}
 update(dt,entities=[]){if(!Number.isFinite(dt)||dt<=0)return;this.time+=dt;this.shake=Math.max(0,this.shake-dt);this.stop=0;this.cinematicRemaining=Math.max(0,this.cinematicRemaining-dt);dt=Math.min(dt,.1);for(const s of this.splats){if(s.active){s.age+=dt;if(s.age>=s.life)s.active=false;}}for(const p of this.pool){if(!p.active)continue;p.age+=dt;p.z=(p.z??.012)+(p.vz??0)*dt;p.vz=(p.vz??0)-.8*dt;if(p.kind==='blood'&&p.z<=0){this.deposit(p);p.active=false;continue;}if(p.age>=p.life){p.active=false;continue;}p.px=p.x;p.py=p.y;const drag=Math.exp(-FX_CONFIG.drag*dt);p.vx*=drag;p.vy=p.vy*drag+(p.kind==='poison'?-.06:FX_CONFIG.gravity)*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;contain(p,this.arena);if(p.kind!=='poison'){for(const body of entities){const dx=p.x-body.x,dy=p.y-body.y,d=Math.hypot(dx,dy),r=body.radius+p.radius;if(d>0&&d<r){const nx=dx/d,ny=dy/d;p.x=body.x+nx*r;p.y=body.y+ny*r;const approach=(p.vx-body.vx)*nx+(p.vy-body.vy)*ny;if(approach<0){p.vx-=1.25*approach*nx;p.vy-=1.25*approach*ny;}}}}contain(p,this.arena);}}
 deposit(p){const s=this.splats.find(s=>!s.active)||this.splats.reduce((a,b)=>a.age>b.age?a:b),radius=p.radius*1.45,point={x:p.x,y:p.y,radius:radius*1.5};contain(point,this.arena,false);Object.assign(s,{active:true,x:point.x,y:point.y,radius,color:p.color,age:0,life:FX_CONFIG.splatLife});}
 renderGround(c,scale=170,reduced=false){if(reduced)return;for(const s of this.splats){if(!s.active)continue;c.globalAlpha=.4*(1-s.age/s.life);c.fillStyle=s.color;c.beginPath();c.ellipse(s.x*scale,s.y*scale,s.radius*scale*1.5,s.radius*scale,0,0,Math.PI*2);c.fill();}c.globalAlpha=1;}
 render(c,scale=170,reduced=false){for(const p of this.pool){if(!p.active)continue;c.globalAlpha=Math.max(0,1-p.age/p.life)*(p.kind==='poison'?.55:1);c.fillStyle=p.color;c.strokeStyle=p.color;if(p.kind==='spark'&&!reduced){c.lineWidth=.7;c.beginPath();c.moveTo(p.px*scale,p.py*scale);c.lineTo(p.x*scale,p.y*scale);c.stroke();}else{c.beginPath();c.arc(p.x*scale,p.y*scale,p.radius*scale*(p.kind==='poison'?2:1),0,Math.PI*2);c.fill();}}c.globalAlpha=1;}
 offset(reduced=false){return reduced||!this.shake?[0,0]:[Math.sin(this.time*137)*FX_CONFIG.maxShake*this.shakePower*this.shake/.14,Math.cos(this.time*173)*FX_CONFIG.maxShake*this.shakePower*this.shake/.14];}
 timeScale(reduced=false){if(reduced||this.cinematicRemaining<=0)return 1;const progress=1-this.cinematicRemaining/this.cinematicDuration;const eased=progress*progress*(3-2*progress);return this.cinematicFactor+(1-this.cinematicFactor)*eased;}
 cameraFocus(reduced=false){const weight=reduced?0:this.cinematicFactor<1?(1-this.timeScale())/(1-this.cinematicFactor):0;return {x:this.focusX,y:this.focusY,zoom:1+.15*weight};}
 snapshot(){return {arena:{...this.arena},rng:this.rng,cinematicRemaining:this.cinematicRemaining,cinematicDuration:this.cinematicDuration,cinematicFactor:this.cinematicFactor,focusX:this.focusX,focusY:this.focusY,time:this.time,cursor:this.cursor,shake:this.shake,stop:this.stop,spawned:this.spawned,shakePower:this.shakePower,lastHeavy:this.lastHeavy,splats:this.splats.filter(s=>s.active).map(s=>({...s})),particles:this.pool.filter(p=>p.active).map(p=>({...p}))};}
 restore(s,run){this.reset(run??{arena:s?.arena});if(!s||s.arena!==undefined&&!validArena(s.arena)||!['time','cursor','shake','stop','spawned'].every(k=>Number.isFinite(s[k])&&s[k]>=0)||!Array.isArray(s.particles)||s.particles.length>FX_CONFIG.capacity)return false;for(const p of s.particles){if(!p||!['x','y','px','py','vx','vy','age','life','radius'].every(k=>Number.isFinite(p[k]))||!Object.hasOwn(colors,p.kind)||!validColor(p.kind,p.color)||['z','vz'].some(k=>p[k]!==undefined&&!Number.isFinite(p[k]))||p.life<=0||p.radius<=0||p.radius>.02||p.age<0)return false;}for(const k of ['time','cursor','shake','stop','spawned'])this[k]=s[k];this.stop=0;this.rng=Number.isInteger(s.rng)?s.rng:1;this.cinematicDuration=Number.isFinite(s.cinematicDuration)&&s.cinematicDuration>0?Math.min(1,s.cinematicDuration):FX_CONFIG.cinematicDuration;this.cinematicFactor=Number.isFinite(s.cinematicFactor)?clamp(s.cinematicFactor,.1,1):FX_CONFIG.cinematicFactor;this.cinematicRemaining=Number.isFinite(s.cinematicRemaining)?clamp(s.cinematicRemaining,0,this.cinematicDuration):0;this.focusX=Number.isFinite(s.focusX)?clamp(s.focusX,0,this.arena.width):this.arena.width/2;this.focusY=Number.isFinite(s.focusY)?clamp(s.focusY,0,this.arena.height):this.arena.height/2;s.particles.forEach((p,i)=>Object.assign(this.pool[i],{z:.012,vz:.1},p));this.shakePower=Number.isFinite(s.shakePower)?clamp(s.shakePower,0,1):1;this.lastHeavy=Number.isFinite(s.lastHeavy)?s.lastHeavy:-1;if(Array.isArray(s.splats)&&s.splats.length<=FX_CONFIG.splatCapacity){s.splats.filter(p=>p&&['x','y','radius','age','life'].every(k=>Number.isFinite(p[k]))&&p.radius>0&&p.radius<.05&&p.life>0&&p.age>=0&&validColor('blood',p.color)).forEach((p,i)=>Object.assign(this.splats[i],p));}return true;}
}
